with filtered as (select *, concat(full_name, ' - ', email) full_name_email from employees where hire_date >= to_date('2023-05-28') and job_title is not null) select manager_id, case when salary >= 161000 then 'HIGH' else 'LOW' end as salary_tier, sum(case when level = 'L4' then salary else 0 end) as l4_salary, round(sum(salary) / nullif(count(case when level = 'L1' then 1 end), 0), 2) as salary_per_l1 from filtered group by manager_id, case when salary >= 161000 then 'HIGH' else 'LOW' end having salary_per_l1 > 0 order by salary_per_l1 nulls last;
